    downloadFile: {
        parameters: {
            query: {
                /** @description Expiry of the link, Unix seconds. */
                exp: number;
                /** @description HMAC signature over the method, the key and every other query parameter. */
                sig: string;
                /** @description Content type to answer with; `application/octet-stream` when absent. */
                type?: string;
                /** @description File name for `Content-Disposition`. */
                name?: string;
            };
            header?: never;
            path: {
                /**
                 * @description Object key `ws/{workspace_id}/{kind}/{uuid}`. It spans several path
                 *     segments: the slashes are sent unescaped.
                 */
                key: string;
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /**
             * @description The file, always as an attachment (`Content-Disposition`, `nosniff`, sandbox CSP,
             *     `Cache-Control: private, no-store`). Range and conditional requests are supported.
             */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/octet-stream": string;
                };
            };
            /** @description Partial content for a `Range` request. */
            206: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            403: components["responses"]["LinkRejected"];
            404: components["responses"]["NotFound"];
        };
    };
    uploadFile: {
        parameters: {
            query: {
                /** @description Expiry of the link, Unix seconds. */
                exp: number;
                /** @description HMAC signature over the method, the key and every other query parameter. */
                sig: string;
                /** @description Largest accepted body, bytes. */
                max: number;
                /** @description Exact body size, bytes, when the link fixes it. */
                size?: number;
                /** @description Required `Content-Type` of the request when present. */
                type?: string;
                /** @description Hex SHA-256 the body must match when present. */
                sha256?: string;
            };
            header?: never;
            path: {
                /**
                 * @description Object key `ws/{workspace_id}/{kind}/{uuid}`. It spans several path
                 *     segments: the slashes are sent unescaped.
                 */
                key: string;
            };
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/octet-stream": string;
            };
        };
        responses: {
            /** @description Stored (an empty body, as S3 answers a PUT). */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description `size_mismatch` or `checksum_mismatch`. */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
            403: components["responses"]["LinkRejected"];
            /** @description `upload_timeout`: the client was too slow; nothing was stored. */
            408: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
            /** @description `already_uploaded`: the link has been used. */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
            /** @description `file_too_large`. */
            413: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
            /** @description `content_type_mismatch`: `Content-Type` differs from the link. */
            415: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
        };
    };
